"""Stroke localization and secondary-prevention section."""
from create_stroke import q,rows,AIS,SP,DIS,ref
LOC=ref('MSD Professional: Stroke Syndromes and Vascular Localization','https://www.msdmanuals.com/professional/neurologic-disorders/stroke/overview-of-stroke')

q('Sudden nonfluent speech with relatively preserved comprehension accompanies right face/arm weakness greater than leg weakness. Which territory is most likely?', 'Dominant superior-division middle cerebral artery',[
 ('Nondominant posterior cerebral artery','This more often causes visual or other posterior deficits, not the classic Broca/face-arm pattern.'),('Anterior cerebral artery','Leg-predominant weakness and medial frontal signs are more typical.'),('Posterior inferior cerebellar artery','This causes a brainstem/cerebellar rather than dominant frontal language syndrome.')],
 'Language phenotype and motor distribution localize together', '**Dominant inferior frontal injury can produce Broca-type aphasia.**', ['The lateral motor cortex emphasizes face and upper limb.','Larger MCA lesions can have broader deficits.'], '**Localize without delaying the acute pathway.**', ['Aphasia can be disabling even with a low NIHSS.','Vascular imaging determines whether an actionable proximal occlusion is present.'], [['Dominant frontal language','Nonfluent output'],['Lateral motor cortex','Face/arm predominance'],['Action','Urgent stroke evaluation']], [LOC,AIS], 'clinical_scenario')
q('Fluent but meaningless speech with poor comprehension and a right visual-field deficit occurs suddenly. Which arterial territory is favored?', 'Dominant inferior-division MCA',[
 ('Dominant ACA','This is not the characteristic posterior temporal language territory.'),('Right PICA','This does not produce the dominant posterior language syndrome.'),('Left anterior spinal artery','This would not explain cortical aphasia.')],
 'Posterior dominant language dysfunction has a different profile from Broca aphasia', '**Wernicke-type aphasia features impaired comprehension with fluent abnormal output.**', ['A field deficit can occur from nearby optic-radiation involvement.','Motor weakness may be less prominent than in a superior-division lesion.'], '**Do not mistake fluency for intact communication.**', ['Assess comprehension and naming.','Sudden onset requires acute vascular assessment.'], [['Superior dominant MCA','More nonfluent language'],['Inferior dominant MCA','Fluent comprehension-impaired language'],['Adjacent visual pathways','Field deficit']], [LOC], 'clinical_scenario')
q('A patient develops a right homonymous hemianopia with relatively preserved central vision and little motor weakness. Which territory is most likely?', 'Left posterior cerebral artery, involving occipital cortex',[
 ('Right anterior cerebral artery','This would more often affect the left leg.'),('Left superior MCA division','Face/arm weakness and language output deficits are more characteristic.'),('Right lateral medulla','This causes a crossed brainstem sensory/bulbar syndrome.')],
 'A cortical visual deficit can be the principal stroke manifestation', '**Occipital injury produces a contralateral homonymous field loss.**', ['Macular sparing can occur but is not required.','PCA disease can also involve thalamic or medial temporal structures.'], '**Assess functional disability rather than limb strength alone.**', ['A visual field defect can prevent safe work or driving.','Normal motor strength does not exclude a disabling stroke.'], [['Occipital cortex','Contralateral field defect'],['PCA','Posterior cortical territory'],['Disability','Can be substantial without paresis']], [LOC,AIS], 'clinical_scenario')
q('Contralateral leg-predominant weakness, abulia and urinary incontinence occur after sudden onset. Which territory is favored?', 'Anterior cerebral artery',[
 ('Inferior MCA division','Posterior temporal language or neglect patterns are more typical.'),('AICA','This is a lateral pontine/cerebellar circulation.'),('PCA occipital branch','Visual deficits are more characteristic.')],
 'The medial frontal surface contains the leg motor representation', '**ACA ischemia can affect leg strength and medial frontal behavior.**', ['Abulia reflects impaired initiation.','Bilateral ACA involvement can produce profound akinetic states.'], '**Distinguish a cortical vascular pattern from an isolated peripheral leg disorder.**', ['Behavioral and bladder findings add localization.','Confirm with brain and vascular imaging.'], [['Motor pattern','Leg more than arm'],['Frontal signs','Abulia/incontinence'],['Territory','ACA']], [LOC])
q('A small infarct causes pure motor hemiparesis of face, arm and leg without aphasia, neglect or a field defect. Which location is classic?', 'Posterior limb of the internal capsule',[
 ('Dominant posterior temporal cortex','Aphasia would be expected in a characteristic cortical lesion.'),('Occipital cortex','This primarily affects vision.'),('Lateral medulla','This does not usually produce a pure dense motor syndrome.')],
 'Compact descending fibers can produce a broad motor deficit from a small lesion', '**A capsular lacune can affect corticospinal and corticobulbar pathways.**', ['The pons is another possible pure-motor lacunar location.','The absence of cortical signs supports a subcortical hypothesis but is not absolute proof of mechanism.'], '**Investigate vascular risk and mechanism appropriately.**', ['Small-vessel disease is common, but a small infarct can have another cause.','Do not omit acute reperfusion assessment solely because the syndrome sounds lacunar.'], [['Internal capsule','Compact motor tract'],['Cortical signs absent','Supports subcortical localization'],['Etiology','Requires assessment']], [LOC,AIS])
q('A small stroke produces contralateral hemisensory loss without major weakness or cortical signs. Which site is classic?', 'Thalamus',[
 ('Primary motor cortex alone','This would primarily produce a motor deficit.'),('Cerebellar hemisphere','Ataxia is more characteristic than a pure hemisensory syndrome.'),('Oculomotor nucleus','This produces an eye-movement/pupillary syndrome.')],
 'A sensory relay lesion can affect several modalities together', '**Thalamic lacunar injury can produce a pure sensory stroke.**', ['Painful central post-stroke symptoms may develop later.','Distribution and modality help refine the specific pathway involved.'], '**Do not equate a mild examination with absence of meaningful symptoms.**', ['Sensory loss can impair function and safety.','Assess vascular causes and secondary prevention.'], [['Thalamus','Sensory relay'],['Pure sensory syndrome','Classic lacunar phenotype'],['Later complication','Central post-stroke pain']], [LOC])
q('Sudden dysphagia, hoarseness, ipsilateral facial pain-temperature loss, contralateral body pain-temperature loss, Horner syndrome and ataxia suggest which lesion?', 'Lateral medulla',[
 ('Medial medulla','This more often involves contralateral weakness and ipsilateral tongue weakness.'),('Internal capsule','It does not explain crossed cranial/body sensory and bulbar signs.'),('Occipital cortex','It does not produce the crossed brainstem pattern.')],
 'Crossed findings point to the brainstem', '**Lateral medullary ischemia commonly involves vertebral/PICA territory.**', ['Nucleus ambiguus involvement explains dysphagia and dysphonia.','Descending sympathetic and spinothalamic/trigeminal pathways explain the other signs.'], '**Protect swallowing and assess the vertebrobasilar circulation.**', ['Posterior stroke can be missed on early CT.','A low NIHSS can underestimate disabling bulbar disease.'], [['Bulbar signs','Nucleus ambiguus'],['Crossed sensation','Brainstem pathways'],['Horner/ataxia','Adjacent lateral structures']], [LOC,AIS], 'clinical_scenario')
q('A lateral brainstem stroke includes ipsilateral lower motor neuron facial weakness and acute hearing loss with vertigo. Which territory is especially suggested?', 'AICA/lateral pontine territory',[
 ('PICA/lateral medulla','Prominent facial motor and auditory involvement favors a pontine/AICA pattern.'),('ACA','This is a medial hemispheric territory.'),('PCA occipital cortex','This would more likely cause a visual field deficit.')],
 'Facial and auditory structures help distinguish lateral pontine from medullary disease', '**AICA-related ischemia can involve facial pathways and the inner-ear blood supply.**', ['Cerebellar and vestibular signs may accompany it.','An acute audiovestibular syndrome can be vascular, not always peripheral benign vertigo.'], '**Use central signs to escalate the diagnostic pathway.**', ['Assess brain and vascular imaging.','Do not let hearing loss automatically exclude stroke.'], [['AICA/lateral pons','Facial motor/auditory clues'],['PICA/lateral medulla','Bulbar/crossed sensory pattern'],['Vertigo','Requires contextual localization']], [LOC], 'clinical_scenario')
q('A conscious patient is quadriplegic and anarthric but communicates with vertical eye movements after basilar occlusion. Which structure is classically injured?', 'Bilateral ventral pons',[
 ('Bilateral occipital cortex','This affects vision rather than producing the classic motor disconnection.'),('Unilateral cerebellar hemisphere','This does not explain quadriplegia with preserved awareness.'),('Cauda equina','This cannot explain anarthria and the cranial communication pattern.')],
 'Motor output can be lost while consciousness is preserved', '**Locked-in syndrome reflects corticospinal/corticobulbar disruption with relative preservation of arousal pathways.**', ['Vertical eye movement and blinking can provide communication.','It must be distinguished from coma.'], '**Establish a reliable communication channel and treat the vascular emergency.**', ['Urgent basilar reperfusion assessment can be relevant early.','Support ventilation, swallowing and rehabilitation needs.'], [['Ventral pontine injury','Motor disconnection'],['Consciousness','Can remain intact'],['Communication','Eye movement/blinking']], [LOC,AIS], 'clinical_scenario')
q('Bilateral border-zone infarcts occur after profound systemic hypotension in a patient with severe carotid disease. Which mechanism is most plausible?', 'Hemodynamic hypoperfusion, potentially interacting with embolic mechanisms',[
 ('A single isolated deep perforator occlusion as the only explanation','The bilateral border-zone distribution and hypotension suggest a broader perfusion problem.'),('A pure peripheral neuropathy','This does not produce brain infarcts.'),('A mandatory diagnosis of venous sinus thrombosis','The distribution and hemodynamic trigger favor a different pathway.')],
 'The most distal perfusion zones are vulnerable to low flow', '**Watershed regions lie at arterial border zones.**', ['Proximal stenosis reduces reserve.','Emboli can also contribute, so distribution alone is not complete mechanistic proof.'], '**Correct the perfusion problem and identify the vascular substrate.**', ['Avoid unnecessary hypotension.','Evaluate carotid and cardiac sources as indicated.'], [['Border zones','Low-flow vulnerability'],['Carotid disease','Reduced reserve'],['Mechanism','May be mixed']], [LOC,SP], 'clinical_scenario')
q('A young adult has unilateral neck pain, partial Horner syndrome and ipsilateral retinal/cerebral ischemia after minor neck strain. What is the key diagnosis?', 'Cervical internal carotid artery dissection',[
 ('Painless uncomplicated migraine as the only possible cause','Painful Horner with ischemia is a vascular warning pattern.'),('Myasthenia gravis','It does not explain miosis and arterial ischemia.'),('Isolated diabetic third-nerve palsy','The examination and vascular phenotype differ.')],
 'A painful sympathetic deficit can reveal an arterial wall lesion', '**Carotid dissection can affect pericarotid sympathetic fibers and generate emboli.**', ['CTA or MRA assesses the vessel.','Antithrombotic choice is individualized, commonly for at least 3–6 months.'], '**Assess acute reperfusion eligibility separately from longer-term treatment.**', ['Dissection does not automatically exclude all acute stroke therapies.','Counsel about recurrence and neck-injury risk during healing.'], [['Painful partial Horner','Carotid dissection clue'],['CTA/MRA','Vessel diagnosis'],['Antithrombotic duration','Individualized 3–6 months']], [DIS], 'clinical_scenario')
q('A medically suitable patient has a recent nondisabling ipsilateral stroke and 80% extracranial carotid stenosis. Which prevention option is strongly supported if procedural risk is acceptable?', 'Carotid endarterectomy with optimal medical therapy',[
 ('No intervention because all symptomatic stenoses behave like incidental mild disease','Severe symptomatic stenosis has substantial recurrent risk.'),('Routine intracranial stenting as the identical procedure','This is a different vessel location and evidence base.'),('Antibiotics alone','They do not treat atherosclerotic stenosis.')],
 'Degree of stenosis, symptoms and timing define the benefit group', '**CEA benefits selected symptomatic 70–99% stenosis when perioperative stroke/death risk is below the accepted threshold.**', ['Early treatment, often within two weeks in a stable suitable patient, maximizes benefit.','A large disabling infarct, hemorrhage or unstable condition can change timing and suitability.'], '**Continue comprehensive medical prevention.**', ['Antiplatelet, lipid, blood-pressure and smoking management remain necessary.','Endarterectomy is not a replacement for risk control.'], [['Severe symptomatic stenosis','CEA assessment'],['Procedure risk','Must be acceptable'],['Timing','Early when safe']], [SP], 'clinical_scenario')
q('For a suitable early minor noncardioembolic stroke or high-risk TIA, what is the usual aspirin–clopidogrel strategy?', 'A short early course, commonly about 21 days in the uncomplicated minor-stroke pathway, followed by single-agent therapy',[
 ('Lifelong DAPT in every case','Bleeding risk outweighs routine long-term benefit.'),('No antiplatelet treatment because symptoms were mild','Early recurrence risk can still be important.'),('Full-dose anticoagulation for every TIA without identifying a mechanism','This is not the standard noncardioembolic strategy.')],
 'The main gain is concentrated early', '**Short DAPT reduces early recurrent ischemia in selected patients.**', ['Some specific mechanisms use a longer selected course.','Eligibility, onset timing, infarct severity and bleeding risk matter.'], '**Write the stop/transition date at the start.**', ['Avoid accidental indefinite combination treatment.','AF or another mechanism can require a different regimen.'], [['Usual minor-stroke pathway','Short DAPT'],['Long term','Single agent usually'],['Specific mechanism','May modify duration']], [AIS,SP])
q('A patient has recent stroke from severe 70–99% intracranial atherosclerotic stenosis. What is the preferred initial prevention direction?', 'Aggressive medical management, including selected short-term DAPT and intensive risk-factor control, rather than routine first-line intracranial stenting',[
 ('Stent every lesion immediately before medical treatment','Trials do not support routine initial stenting.'),('Treat blood pressure and lipids as irrelevant','These are central to outcome.'),('Use indefinite triple antithrombotic therapy regardless of bleeding','This lacks a routine benefit and adds harm.')],
 'The intracranial evidence differs from extracranial carotid endarterectomy', '**Selected severe symptomatic disease can use aspirin–clopidogrel for up to 90 days under the appropriate protocol.**', ['High-intensity lipid therapy and blood-pressure/lifestyle management are essential.','Recurrent events despite optimized care require expert review, not automatic procedural escalation.'], '**Confirm the mechanism and adherence.**', ['An incidental stenosis is not necessarily the cause of every infarct.','Bleeding risk and hemorrhagic transformation affect antithrombotic decisions.'], [['Initial treatment','Aggressive medical care'],['DAPT','Selected limited duration'],['Stenting','Not routine first-line']], [SP])
q('A patient with ischemic stroke is found to have nonvalvular AF. What is the long-term antithrombotic principle?', 'Use an appropriate oral anticoagulant when safe, with initiation timing individualized to infarct and bleeding features',[
 ('Aspirin is always equivalent to anticoagulation for AF stroke prevention','It is generally less effective for this mechanism.'),('Start full-dose IV heparin immediately in every infarct','Acute anticoagulation timing is not universal and can increase bleeding risk.'),('A DOAC is appropriate for every mechanical heart valve','Mechanical valves require a different anticoagulant framework.')],
 'Mechanism determines the prevention class', '**AF-related embolism is usually an anticoagulation indication rather than an antiplatelet-only problem.**', ['Infarct size, hemorrhagic transformation and current evidence guide start timing.','Renal function, interactions and valve status influence agent selection.'], '**Avoid unnecessary combined antiplatelet therapy.**', ['A separate coronary indication can change the balance.','Address rhythm detection and other vascular risks as well.'], [['AF mechanism','Oral anticoagulation'],['Start time','Individualized safety assessment'],['Mechanical valve','Different drug rules']], [AIS,SP], 'clinical_scenario')
q('An embolic-appearing stroke remains of undetermined source after an appropriate evaluation. Should all such patients receive empiric anticoagulation?', 'No; unselected ESUS does not justify routine empiric anticoagulation over antiplatelet therapy',[
 ('Yes, because an embolic imaging pattern proves AF','Several non-AF mechanisms can produce embolic infarcts.'),('No further rhythm assessment is ever useful','Longer monitoring can uncover occult AF in selected patients.'),('Triple therapy is the universal solution','This adds bleeding without a routine indication.')],
 'A morphological suspicion is not the same as a proven anticoagulant-responsive mechanism', '**ESUS trials did not establish a universal anticoagulation benefit.**', ['Continue mechanism investigation where appropriate.','If AF or another clear indication is found, the plan changes.'], '**Use evidence-based prevention while uncertainty remains.**', ['Antiplatelet and vascular-risk treatment are usual components.','Do not allow the label to replace a complete diagnostic review.'], [['Unselected ESUS','No routine empiric anticoagulation'],['Occult AF found','Mechanism-specific anticoagulation'],['Ongoing assessment','Selected monitoring']], [SP])
q('A 42-year-old has a nonlacunar cryptogenic ischemic stroke after thorough assessment and a PFO with high-risk anatomy. What is reasonable?', 'Joint stroke/cardiology assessment for PFO closure plus long-term antiplatelet therapy',[
 ('Close every incidentally found PFO at every age','Causality and the evidence-supported population matter.'),('Assume a PFO excludes AF or atherosclerosis','Competing mechanisms must be evaluated.'),('No discussion because a PFO can never cause stroke','Paradoxical embolism is relevant in selected patients.')],
 'A common anatomical finding is only sometimes causal', '**Evidence supports selected patients aged 18–60 with an otherwise unexplained nonlacunar event and appropriate features.**', ['Assess the likelihood the PFO caused the event.','Procedural risks, including AF, enter shared decision making.'], '**Do not skip the etiological work-up.**', ['A high-risk alternative cause can change the benefit.','Closure does not eliminate all future vascular risk.'], [['Selected young cryptogenic phenotype','Closure discussion'],['Incidental PFO','Not automatic causation'],['Decision','Neurology/cardiology plus patient']], [SP], 'clinical_scenario')
q('For a patient with ischemic stroke and atherosclerotic disease, what lipid strategy is generally appropriate?', 'High-intensity statin therapy and an LDL-C target below 70 mg/dL, adding appropriate agents if needed',[
 ('Stop lipid treatment once the acute weakness improves','The recurrent vascular risk remains.'),('Use HDL alone as the treatment target','LDL lowering has the relevant evidence base.'),('Avoid statins solely because a stroke occurred','They are a major component of appropriate secondary prevention.')],
 'Prevent the next vascular event rather than treating only current symptoms', '**Intensive LDL reduction is recommended in the appropriate atherosclerotic stroke population.**', ['Use the maximally tolerated regimen.','Ezetimibe or selected additional agents can be needed when targets are not reached.'], '**Treat global risk at the same time.**', ['Smoking, hypertension, diabetes and activity matter.','Monitor safety and adherence rather than assuming a prescription guarantees exposure.'], [['Core drug','High-intensity statin'],['LDL goal','<70 mg/dL in the relevant framework'],['Residual elevation','Add-on assessment']], [SP])
q('What is a common long-term blood-pressure goal for most hypertensive stroke survivors once the acute phase is over?', 'Below 130/80 mmHg when tolerated and appropriate',[
 ('Maintain 220/120 indefinitely','Acute permissive thresholds do not define chronic prevention goals.'),('Force every patient to systolic 80 mmHg','Excess hypotension is harmful.'),('Avoid all treatment if the stroke was painless','Pain is irrelevant to recurrent vascular risk.')],
 'Acute perfusion management and chronic prevention have different targets', '**Long-term control reduces recurrent stroke and other vascular events.**', ['Comorbidity, stenosis, orthostasis and frailty can modify the individual target.','Use home measurements and adherence review.'], '**Do not carry an acute no-lowering instruction into lifelong care.**', ['Transition deliberately after stabilization.','Lifestyle and medication strategies are complementary.'], [['Acute phase','Reperfusion/perfusion-dependent rules'],['Chronic phase','Usually <130/80 if suitable'],['Individualization','Tolerance and anatomy']], [SP])
q('An immobile stroke patient has no contraindication to mechanical prophylaxis. Which measure reduces venous thromboembolism risk?', 'Intermittent pneumatic compression',[
 ('Elastic compression stockings alone as an equivalent evidence-based substitute','Stockings alone do not provide the same demonstrated benefit in immobile stroke.'),('No prevention until symptomatic pulmonary embolism','Immobility creates a preventable risk.'),('Full-dose anticoagulation for every patient solely because they cannot walk','Therapeutic dosing is not routine prophylaxis and may be unsafe.')],
 'Immobility creates a second vascular hazard', '**IPC is an evidence-supported mechanical preventive measure.**', ['Pharmacological prophylaxis is chosen according to hemorrhagic risk and timing.','Early appropriate mobilization and rehabilitation also matter.'], '**Distinguish prophylactic from therapeutic anticoagulation.**', ['An established DVT/PE requires a separate assessment.','ICH and post-thrombolysis settings impose additional timing constraints.'], [['IPC','Mechanical prevention'],['Prophylactic anticoagulant','Risk/timing dependent'],['Therapeutic dose','Separate indication']], [AIS])
